import React from 'react';
import { Typography, Button, Descriptions, Image } from 'antd';
import { CheckOutlined, CloseCircleOutlined, FileImageOutlined } from '@ant-design/icons';
import Pill from '@/components/pill/Pill';
import { BusinessAppContextProps } from '@/common/BusinessAppContext';
import { formatDate } from '@/common/utils/windowUtils';

const { Title, Text } = Typography;

export interface ExpenseRequestDetailsProps extends BusinessAppContextProps {
  request: any;
  onApprove: (requestId: string) => void;
  onReject: (requestId: string) => void;
}

const ExpenseRequestDetails: React.FC<ExpenseRequestDetailsProps> = ({
  request,
  onApprove,
  onReject
}) => {
  const handleApprove = () => {
    onApprove(request.id);
  };

  const handleReject = () => {
    onReject(request.id);
  };

  const renderAttachments = () => {
    if (!request.attachments || request.attachments.length === 0) {
      return <Text type="secondary">No attachments</Text>;
    }

    return (
      <div className="gba:flex gba:flex-wrap gba:gap-2">
        {request.attachments.map((attachment: any, index: number) => (
          <div key={index} className="gba:border gba:rounded gba:p-2 gba:flex gba:flex-col gba:items-center">
            {attachment.fileUrl ? (
              <Image
                src={attachment.fileUrl}
                alt={`Attachment ${index + 1}`}
                width={100}
                height={100}
                style={{ objectFit: 'cover' }}
                fallback="data:image/png;base64,"
              />
            ) : (
              <FileImageOutlined style={{ fontSize: '48px', color: '#d9d9d9' }} />
            )}
            <Text ellipsis style={{ maxWidth: '100px' }}>
              {attachment.fileName || `File ${index + 1}`}
            </Text>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="gba:p-6">
      <div className="gba:mb-6">
        <Pill 
          type={request.status === 'APPROVED' ? 'completed' :
                request.status === 'REJECTED' ? 'error' :
                request.status === 'DRAFT' ? 'draft' : 'waiting'}
          label={request.status}
        />
      </div>

      <Descriptions bordered column={1} size="small" className="gba:mb-6">
        <Descriptions.Item label="Title">{request.title}</Descriptions.Item>
        <Descriptions.Item label="Employee">{request.employee?.fullName}</Descriptions.Item>
        <Descriptions.Item label="Department">{request.employee?.department}</Descriptions.Item>
        <Descriptions.Item label="Request Date">{request.requestDate ? formatDate(request.requestDate, 'date.short') : '-'}</Descriptions.Item>
        <Descriptions.Item label="Amount">€{request.amount?.toFixed(2)}</Descriptions.Item>
        <Descriptions.Item label="Description">{request.description || 'No description provided'}</Descriptions.Item>
      </Descriptions>

      <div className="gba:mb-6">
        <Title level={5} className="gba:mb-2">Attachments</Title>
        {renderAttachments()}
      </div>

      {request.status === 'PENDING' && (
        <div className="gba:mt-6 gba:flex gba:justify-end gba:gap-4">
          <Button 
            danger
            icon={<CloseCircleOutlined />}
            onClick={handleReject}
          >
            Reject
          </Button>
          <Button 
            type="primary"
            icon={<CheckOutlined />}
            onClick={handleApprove}
          >
            Approve
          </Button>
        </div>
      )}
    </div>
  );
};

export default ExpenseRequestDetails;
